-- CollabNexus baseline schema for H2 2.x.
-- Generated from the JPA entity model. Keep this file in sync with the entities.

create table audit_logs (actor_id bigint, created_at timestamp(6) with time zone not null, entity_id bigint, id bigint generated by default as identity, entity_type varchar(40) not null, action varchar(80) not null, details varchar(1000), primary key (id));
create table brand_profiles (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null unique, version bigint, country varchar(120), industry varchar(120), company_name varchar(160) not null, logo_url varchar(500), description varchar(2000), website varchar(255), primary key (id));
create table campaign_applications (available_from date, currency varchar(3) not null, proposed_price numeric(12,2), campaign_id bigint not null, created_at timestamp(6) with time zone not null, creator_id bigint not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, version bigint, portfolio_url varchar(500), proposal varchar(2000) not null, status enum ('ACCEPTED','PENDING','REJECTED','SHORTLISTED','WITHDRAWN') not null, primary key (id), constraint uk_application_campaign_creator unique (campaign_id, creator_id));
create table campaigns (application_deadline date not null, creators_required integer not null, currency varchar(3) not null, end_date date not null, max_budget numeric(12,2) not null, min_budget numeric(12,2) not null, start_date date not null, brand_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, version bigint, category varchar(120), title varchar(160) not null, deliverable_requirements varchar(2000), objectives varchar(2000), product_details varchar(2000), review_rules varchar(2000), target_audience varchar(2000), description varchar(4000) not null, content_formats varchar(255), niches varchar(255), platforms varchar(255), compensation_model enum ('AFFILIATE','FIXED_FEE','HYBRID','PER_DELIVERABLE') not null, status enum ('CLOSED','DRAFT','PAUSED','PUBLISHED') not null, primary key (id));
create table collaborations (agreed_amount numeric(12,2), currency varchar(3) not null, application_id bigint not null unique, brand_id bigint not null, campaign_id bigint not null, created_at timestamp(6) with time zone not null, creator_id bigint not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, version bigint, status enum ('ACTIVE','CANCELLED','COMPLETED','IN_PROGRESS') not null, primary key (id));
create table contract_acceptances (version_number integer not null, accepted_at timestamp(6) with time zone not null, accepted_by bigint not null, contract_id bigint not null, id bigint generated by default as identity, role enum ('ADMIN','BRAND','CREATOR') not null, primary key (id), constraint uk_contract_acceptance unique (contract_id, version_number, accepted_by));
create table contract_versions (agreed_compensation numeric(12,2), completion_deadline date, currency varchar(3) not null, revision_allowance integer not null, version_number integer not null, contract_id bigint not null, created_at timestamp(6) with time zone not null, created_by bigint not null, id bigint generated by default as identity, cancellation_terms varchar(4000), deliverables_summary varchar(4000), payment_schedule varchar(4000), usage_rights varchar(4000), primary key (id), constraint uk_contract_version unique (contract_id, version_number));
create table contracts (agreed_compensation numeric(12,2), completion_deadline date, currency varchar(3) not null, revision_allowance integer not null, version_number integer not null, brand_acknowledged_at timestamp(6) with time zone, brand_id bigint not null, collaboration_id bigint not null unique, created_at timestamp(6) with time zone not null, creator_acknowledged_at timestamp(6) with time zone, creator_id bigint not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, version bigint, reference_number varchar(40) not null, cancellation_terms varchar(4000), deliverables_summary varchar(4000), payment_schedule varchar(4000), usage_rights varchar(4000), status enum ('ACKNOWLEDGED','DRAFT','PENDING_ACKNOWLEDGEMENT','VOID') not null, primary key (id), constraint uk_contract_reference unique (reference_number));
create table conversation_messages (conversation_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, read_at timestamp(6) with time zone, sender_id bigint not null, body varchar(2000) not null, primary key (id));
create table conversations (brand_id bigint not null, collaboration_id bigint not null unique, created_at timestamp(6) with time zone not null, creator_id bigint not null, id bigint generated by default as identity, last_message_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, subject varchar(160) not null, primary key (id));
create table creator_profiles (base_rate numeric(12,2), currency varchar(3), created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null unique, version bigint, primary_platform varchar(60), country varchar(120), display_name varchar(120) not null, niche varchar(120), headline varchar(160), portfolio_url varchar(500), bio varchar(2000), content_formats varchar(255), languages varchar(255), availability enum ('AVAILABLE','BOOKED','LIMITED','UNAVAILABLE') not null, verification_status enum ('IDENTITY_VERIFIED','UNVERIFIED') not null, primary key (id));
create table deliverable_reviews (created_at timestamp(6) with time zone not null, deliverable_id bigint not null, id bigint generated by default as identity, reviewer_id bigint not null, submission_id bigint not null, comments varchar(2000), action enum ('APPROVED','REJECTED','REVISION_REQUESTED') not null, primary key (id));
create table deliverable_submissions (version_number integer not null, created_at timestamp(6) with time zone not null, deliverable_id bigint not null, file_size bigint, id bigint generated by default as identity, submitted_by bigint not null, content_type varchar(120), stored_file_name varchar(120), submission_url varchar(500), notes varchar(2000), original_file_name varchar(255), primary key (id), constraint uk_deliverable_submission_version unique (deliverable_id, version_number));
create table deliverables (due_date date, revision_number integer not null, collaboration_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, reviewed_at timestamp(6) with time zone, submitted_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, version bigint, content_format varchar(80), platform varchar(80), title varchar(160) not null, description varchar(2000), review_comments varchar(2000), status enum ('APPROVED','IN_PROGRESS','PENDING','REJECTED','REVISION_REQUESTED','SUBMITTED') not null, primary key (id));
create table notifications (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, read_at timestamp(6) with time zone, user_id bigint not null, title varchar(160) not null, link varchar(300), message varchar(600) not null, type enum ('APPLICATION_ACCEPTED','APPLICATION_RECEIVED','APPLICATION_REJECTED','APPLICATION_SHORTLISTED','COLLABORATION_UPDATED','CONTRACT_AWAITING_ACKNOWLEDGEMENT','DELIVERABLE_APPROVED','DELIVERABLE_SUBMITTED','NEW_MESSAGE','PAYMENT_UPDATED','REPORT_RESOLVED','REVISION_REQUESTED') not null, primary key (id));
create table payment_records (amount numeric(12,2) not null, currency varchar(3) not null, due_date date, paid_amount numeric(12,2) not null, brand_id bigint not null, collaboration_id bigint not null, created_at timestamp(6) with time zone not null, creator_id bigint not null, id bigint generated by default as identity, paid_at timestamp(6) with time zone, recorded_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, version bigint, milestone varchar(120) not null, external_reference varchar(160), notes varchar(2000), status enum ('DISPUTED','DUE','FAILED','NOT_DUE','PAID','PROCESSING','REFUNDED') not null, primary key (id));
create table reports (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, reporter_id bigint not null, resolved_at timestamp(6) with time zone, resolved_by bigint, target_id bigint, updated_at timestamp(6) with time zone not null, version bigint, reason varchar(120) not null, admin_notes varchar(2000), details varchar(2000), status enum ('DISMISSED','OPEN','RESOLVED','UNDER_REVIEW') not null, target_type enum ('CAMPAIGN','MESSAGE','OTHER','REVIEW','USER') not null, primary key (id));
create table reviews (rating integer not null, author_id bigint not null, collaboration_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, subject_id bigint not null, updated_at timestamp(6) with time zone not null, version bigint, comment varchar(2000), status enum ('HIDDEN','PUBLISHED','UNDER_REVIEW') not null, primary key (id), constraint uk_review_collaboration_author unique (collaboration_id, author_id));
create table users (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, version bigint, password_hash varchar(100) not null, full_name varchar(120) not null, email varchar(180) not null, role enum ('ADMIN','BRAND','CREATOR') not null, status enum ('ACTIVE','SUSPENDED') not null, primary key (id), constraint uk_users_email unique (email));
create index idx_audit_created on audit_logs (created_at);
create index idx_audit_actor on audit_logs (actor_id);
create index idx_contract_acceptance_contract on contract_acceptances (contract_id);
create index idx_contract_version_contract on contract_versions (contract_id);
create index idx_contract_brand on contracts (brand_id);
create index idx_contract_creator on contracts (creator_id);
create index idx_message_conversation on conversation_messages (conversation_id, created_at);
create index idx_conversation_brand on conversations (brand_id);
create index idx_conversation_creator on conversations (creator_id);
create index idx_review_deliverable on deliverable_reviews (deliverable_id);
create index idx_submission_deliverable on deliverable_submissions (deliverable_id);
create index idx_deliverable_collaboration on deliverables (collaboration_id);
create index idx_deliverable_status on deliverables (status);
create index idx_deliverable_due_date on deliverables (due_date);
create index idx_notification_user on notifications (user_id, created_at);
create index idx_notification_unread on notifications (user_id, read_at);
create index idx_payment_collaboration on payment_records (collaboration_id);
create index idx_payment_brand on payment_records (brand_id);
create index idx_payment_creator on payment_records (creator_id);
create index idx_payment_status on payment_records (status);
create index idx_report_status on reports (status);
create index idx_report_reporter on reports (reporter_id);
create index idx_review_subject on reviews (subject_id, status);
create index idx_review_status on reviews (status);
